// Custom Worker entry (wrangler.jsonc "main"). Legacy WordPress URLs and
// /wp-content/uploads/* are answered here, before Next.js runs; every other
// request goes to the OpenNext handler unchanged.
// https://opennext.js.org/cloudflare/howtos/custom-worker
// Decision record: docs/architecture/LEGACY_URL_AND_MEDIA_LAYER.md
//
// Runs under `pnpm preview` and in production, not under `next dev`.

// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as openNext } from "./.open-next/worker.js";
import { handleLegacyRequest } from "./src/legacy/worker-layer.ts";
import type { MediaBucket } from "./src/legacy/media-handler.ts";

// OpenNext's Durable Object classes (DOQueueHandler, DOShardedTagCache) are not
// re-exported: wrangler.jsonc binds no Durable Objects. Re-export them here if a
// DO-based cache or queue is configured later.

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
    const legacy = await handleLegacyRequest(request, {
      bucket: env.MEDIA as unknown as MediaBucket,
      images: env.IMAGES,
      cache: await caches.open("legacy-media"),
      waitUntil: (p) => ctx.waitUntil(p),
    });
    return legacy ?? openNext.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
